def sandwich(g):
    h,w=len(g),len(g[0])
    vals=[v for r in g for v in r]
    lc=min(vals,key=lambda x:vals.count(x))
    rows=[r for r in range(h) if len(set(g[r]))==1]; cols=[c for c in range(w) if len({g[r][c] for r in range(h)})==1]
    R=set(rows); C=set(cols)
    out=[[g[r][c] for c in range(w)] for r in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]==lc and r not in R and c not in C:
                # vertical sandwich: line above and below, or horizontal sandwich
                vert = (r-1 in R) and (r+1 in R)
                horiz = (c-1 in C) and (c+1 in C)
                if vert or horiz: out[r][c]=2
    return out
for n in (1,2,3,4,5):
    print(n, sandwich(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])
import json; print(json.dumps(sandwich(G['Test input'])))

